css:
.mbl-rail { display: flex; gap: 8px; padding: 0px 16px; align-items: stretch; overflow-x: auto; scrollbar-width: none; }
.mbl-rail::-webkit-scrollbar { display: none; }
.mbl-rail-lg { display: flex; gap: 8px; padding: 0px 16px; align-items: stretch; overflow-x: auto; scrollbar-width: none; }
.mbl-rail-lg::-webkit-scrollbar { display: none; }
.mbl-panel { box-sizing: border-box; min-width: 0px; display: flex; flex-direction: column; border: 1px solid var(--stroke-tertiary, #e4e4e4); border-radius: 16px; background: var(--surface-primary, #fff); }
.mbl-panel--sm { flex: 0 0 204px; padding: 14px 12px; }
.mbl-panel--md { flex: 0 0 240px; padding: 14px 12px; }
.mbl-panel__title { margin: 0px 0px 10px; font-family: var(--font-body); font-size: 16px; font-weight: 700; line-height: 22px; letter-spacing: -0.01em; color: var(--foreground-primary, #191919); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbl-panel__title--sm { margin-bottom: 12px; }
.mbl-panel__title--md { margin-bottom: 10px; }
.mbl-panel__count { font-size: 14px; font-weight: 500; color: var(--foreground-secondary, #606060); letter-spacing: normal; }
.mbl-row { display: flex; align-items: flex-start; cursor: pointer; }
.mbl-row + .mbl-row { margin-top: 12px; }
.mbl-row--sm { gap: 10px; }
.mbl-row--md { gap: 12px; }
.mbl-row__img { position: relative; flex-shrink: 0; overflow: hidden; background: var(--background-secondary, #f1f1f1); }
.mbl-row__img--sm { width: 72px; height: 72px; border-radius: 10px; }
.mbl-row__img--md { width: 96px; height: 96px; border-radius: 12px; }
.mbl-row__img img { width: 100%; height: 100%; object-fit: cover; display: block; }
.mbl-row__info { flex: 1 1 0%; min-width: 0px; min-height: 72px; display: flex; flex-direction: column; }
.mbl-row__store--sm { font-family: var(--font-body); font-size: 13px; font-weight: 700; line-height: 17px; letter-spacing: -0.01em; color: var(--foreground-primary, #191919); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.mbl-row__store--md { font-family: var(--font-body); font-size: 14px; font-weight: 700; line-height: 18px; letter-spacing: -0.01em; color: var(--foreground-primary, #191919); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.mbl-row__dish { margin-top: 1px; font-family: var(--font-body); font-size: 12px; font-weight: 500; line-height: 15px; color: var(--foreground-secondary, #606060); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbl-row__price { margin-top: auto; display: block; min-height: 17px; }
.mbl-card { flex: 0 0 280px; min-width: 0px; display: flex; flex-direction: column; background: var(--surface-primary, #fff); border: 1px solid var(--stroke-tertiary, #e4e4e4); border-radius: 16px; padding: 14px; }
.mbl-card__header { display: flex; align-items: center; gap: 8px; height: 24px; margin-bottom: 8px; cursor: pointer; }
.mbl-card__title { flex: 1 1 0%; min-width: 0px; font-family: var(--font-body); font-size: 17px; font-weight: 700; line-height: 24px; letter-spacing: -0.01em; color: var(--foreground-primary, #191919); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbl-card__count { font-size: 15px; font-weight: 500; color: var(--foreground-secondary, #606060); letter-spacing: normal; }
.mbl-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px 10px; }
.mbl-tile { min-width: 0px; display: flex; flex-direction: column; cursor: pointer; }
.mbl-tile__photo { position: relative; width: 100%; aspect-ratio: 1 / 1; border-radius: 12px; overflow: hidden; background: var(--background-secondary, #f1f1f1); margin-bottom: 4px; }
.mbl-tile__photo img { width: 100%; height: 100%; object-fit: cover; display: block; }
.mbl-tile__store { font-family: var(--font-body); font-size: 13px; font-weight: 700; line-height: 16px; letter-spacing: -0.01em; color: var(--foreground-primary, #191919); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; margin-bottom: 2px; }
.mbl-tile__dish { font-family: var(--font-body); font-size: 12px; font-weight: 500; line-height: 15px; color: var(--foreground-secondary, #606060); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.mbl-tile__price { padding-top: 2px; }
.mbl-seeall { padding: 16px 16px 0px; }
.sh-tile2x2 .mbx-price { margin-bottom: 2px; }
.sh-page .mbx-price__integer { font-weight: 700; }
.sh-page .mbx-price__currency, .sh-page .mbx-price__decimal { font-weight: 500; }
.mbx-section { padding: 28px 0px 0px; }
.mbx-section .section-header { padding: 0px 16px; margin-bottom: 12px; }
.mbx-section .section-subtitle { font-family: "DD Norms", -apple-system, BlinkMacSystemFont, sans-serif; font-size: 14px; font-weight: 500; line-height: 20px; color: var(--foreground-secondary, #606060); }
.mbx-program-header { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 0px 16px; margin-bottom: 12px; }
.mbx-program-header__titles { min-width: 0px; }
.mbx-program-header__title { display: flex; align-items: center; gap: 6px; margin: 0px; font-family: "DD Norms", -apple-system, BlinkMacSystemFont, sans-serif; font-size: var(--title-2-size, 20px); font-weight: var(--title-2-weight, 700); line-height: var(--title-2-lh, 26px); letter-spacing: var(--title-2-ls, normal); color: var(--foreground-primary, #191919); }
.mbx-program-header__glyph { display: flex; align-items: center; justify-content: center; flex-shrink: 0; width: 20px; height: 20px; border-radius: 9999px; background: rgb(235, 23, 0); }
.mbx-program-header__glyph svg path { fill: rgb(255, 255, 255); }
.mbx-program-header__glyph svg { width: 13px; height: 13px; }
.mbx-program-header__sub { margin: 2px 0px 0px; font-family: "DD Norms", -apple-system, BlinkMacSystemFont, sans-serif; font-size: 14px; font-weight: 500; line-height: 20px; color: var(--foreground-secondary, #606060); }
.mbx-eyebrow-header { padding: 0px 16px; margin-bottom: 12px; }
.mbx-eyebrow-header__eyebrow { margin: 0px 0px 2px; font-family: "DD Norms", -apple-system, BlinkMacSystemFont, sans-serif; font-size: 11px; font-weight: 700; line-height: 16px; letter-spacing: 0.06em; text-transform: uppercase; color: rgb(235, 23, 0); }
.mbx-eyebrow-header__title { display: flex; align-items: center; gap: 2px; margin: 0px; font-family: "DD Norms", -apple-system, BlinkMacSystemFont, sans-serif; font-size: var(--title-2-size, 20px); font-weight: var(--title-2-weight, 700); line-height: var(--title-2-lh, 26px); letter-spacing: var(--title-2-ls, normal); color: var(--foreground-primary, #191919); }
.mbx-eyebrow-header__chevron { display: flex; align-items: center; flex-shrink: 0; color: var(--foreground-primary, #191919); }
.mbx-eyebrow-header__chevron svg { width: 20px; height: 20px; }
.mbx-seeall { padding: 16px 16px 0px; }
.mbx-group__store.is-emph { display: flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 700; line-height: 18px; color: var(--foreground-primary, #191919); }
.mbx-group__store-logo { width: 14px; height: 14px; border-radius: 9999px; object-fit: cover; flex-shrink: 0; background: var(--background-secondary, #f1f1f1); }
.mbx-section.mbx-band { position: relative; padding: 16px 0px; background: rgb(255, 245, 243); border-top: 1px solid rgb(247, 213, 207); border-bottom: 1px solid rgb(247, 213, 207); }
.mbx-program-header--band { margin-bottom: 12px; }
.mbx-band .msx6-store-card, .mbx-band .msx6-item-card__img, .mbx-band .mbx-group { background: rgb(255, 255, 255); }
.mbx-price { display: flex; align-items: flex-start; padding-top: 2px; }
.mbx-price__currency { font-family: var(--font-body); font-size: 12px; font-weight: 700; line-height: 16px; color: var(--foreground-primary, #191919); padding-top: 1px; }
.mbx-price__integer { font-family: var(--font-body); font-size: 18px; font-weight: 800; line-height: 22px; color: var(--foreground-primary, #191919); }
.mbx-price__decimal { font-family: var(--font-body); font-size: 12px; font-weight: 700; line-height: 16px; color: var(--foreground-primary, #191919); padding-top: 1px; }
.mbx-price--sm .mbx-price__integer { font-size: 15px; line-height: 19px; }
.mbx-price--sm .mbx-price__currency, .mbx-price--sm .mbx-price__decimal { font-size: 10px; line-height: 13px; }
.mbx-price--xs .mbx-price__integer { font-size: 13px; line-height: 17px; }
.mbx-price--xs .mbx-price__currency, .mbx-price--xs .mbx-price__decimal { font-size: 9px; line-height: 12px; }
.mbx-price--lg .mbx-price__integer { font-size: 18px; line-height: 24px; font-weight: 700; }
.mbx-price--lg .mbx-price__currency { font-size: 12px; line-height: 18px; font-weight: 500; }
.mbx-price--lg .mbx-price__decimal { font-size: 14px; line-height: 20px; font-weight: 500; }
.mbx-rail { display: flex; gap: 12px; overflow-x: auto; padding: 0px 16px; scrollbar-width: none; }
.mbx-rail::-webkit-scrollbar { display: none; }
.mbx-item-card { flex-shrink: 0; width: 157px; cursor: pointer; }
.mbx-item-card__img { position: relative; width: 157px; height: 157px; border-radius: 16px; overflow: hidden; background: var(--background-secondary, #f7f7f7); }
.mbx-item-card__img img { width: 100%; height: 100%; object-fit: cover; display: block; }
.mbx-item-card__name { font-family: var(--font-body); font-size: 14px; font-weight: 700; line-height: 20px; color: var(--foreground-primary, #191919); margin-top: 4px; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.mbx-item-card__store { font-family: var(--font-body); font-size: 12px; font-weight: 500; line-height: 18px; color: var(--foreground-secondary, #606060); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbx-item-card__meta { display: flex; align-items: center; gap: 3px; margin-top: 2px; white-space: nowrap; overflow: hidden; }
.mbx-item-card__eta { font-family: var(--font-body); font-size: 12px; font-weight: 500; line-height: 18px; color: var(--foreground-secondary, #606060); }
.mbx-item-card__tags { display: flex; gap: 4px; margin-top: 4px; }
.mbx-oldcar-item__dish { font-family: var(--font-body); font-size: 14px; font-weight: 700; line-height: 20px; color: var(--foreground-primary, #191919); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbx-oldcar-item__price { font-family: var(--font-body); font-size: 14px; font-weight: 700; line-height: 20px; color: var(--foreground-primary, #191919); margin-top: 4px; }
.mbx-item-card__callout { font-family: var(--font-body); font-size: 12px; font-weight: 500; line-height: 18px; color: var(--foreground-secondary, #606060); margin-top: 2px; }
.mbx-qty-float { position: absolute; bottom: 8px; right: 8px; width: 32px; height: 32px; border-radius: 9999px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: var(--surface-primary, #fff); box-shadow: rgba(25, 25, 25, 0.2) 0px 1px 4px; display: flex; align-items: center; justify-content: center; cursor: pointer; color: var(--foreground-primary, #191919); padding: 0px; }
.mbx-qty-stepper { position: absolute; bottom: 8px; right: 8px; height: 32px; border-radius: 9999px; background: var(--surface-primary, #fff); box-shadow: rgba(25, 25, 25, 0.2) 0px 1px 4px; display: flex; align-items: center; gap: 2px; padding: 0px 4px; }
.mbx-qty-stepper__btn { width: 24px; height: 24px; border-radius: 9999px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: transparent; display: flex; align-items: center; justify-content: center; cursor: pointer; color: var(--foreground-primary, #191919); padding: 0px; }
.mbx-qty-stepper__count { font-family: var(--font-body); font-size: 14px; font-weight: 700; line-height: 20px; color: var(--foreground-primary, #191919); min-width: 16px; text-align: center; }
.mbx-qty-float.mbx-qty--sm { width: 24px; height: 24px; bottom: 6px; right: 6px; }
.mbx-qty-float.mbx-qty--sm svg { width: 10px; height: 10px; }
.mbx-qty-stepper.mbx-qty--sm { height: 24px; bottom: 6px; right: 6px; gap: 0px; padding: 0px 2px; }
.mbx-qty-stepper.mbx-qty--sm .mbx-qty-stepper__btn { width: 20px; height: 20px; }
.mbx-qty-stepper.mbx-qty--sm .mbx-qty-stepper__count { font-size: 12px; line-height: 16px; min-width: 12px; }
.mbx-nested__scroll { display: flex; gap: 12px; overflow-x: auto; padding: 0px 16px; scrollbar-width: none; }
.mbx-nested__scroll::-webkit-scrollbar { display: none; }
.mbx-nested__scroll { animation: 0.18s ease-out 0s 1 normal none running mbx-group-fade; }
.mbx-group { flex-shrink: 0; border: 1px solid var(--stroke-tertiary, #e4e4e4); border-radius: 16px; padding: 12px 16px 16px; overflow: hidden; }
.mbx-group__header { display: flex; align-items: center; justify-content: space-between; gap: 4px; margin-bottom: 12px; }
.mbx-group__title { font-family: var(--font); font-size: 18px; font-weight: 700; line-height: 22px; color: var(--foreground-primary, #191919); flex: 1 1 0%; min-width: 0px; }
.mbx-group__chevron { display: flex; align-items: center; color: var(--foreground-primary, #191919); flex-shrink: 0; }
.mbx-group__chevron svg { width: 16px; height: 16px; }
.mbx-group__layout { display: flex; gap: 8px; }
.mbx-group__main { display: flex; flex-direction: column; width: 140px; flex-shrink: 0; cursor: pointer; }
.mbx-group__main-img { position: relative; width: 140px; height: 140px; border-radius: 16px; overflow: hidden; background: var(--background-secondary, #f1f1f1); }
.mbx-group__main-img img, .mbx-group__side-img img { width: 100%; height: 100%; object-fit: cover; display: block; }
.mbx-group__main-meta { padding-top: 6px; }
.mbx-group__name { font-family: var(--font-body); font-size: 14px; font-weight: 500; line-height: 20px; color: var(--foreground-primary, #191919); overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.mbx-group__side { display: flex; flex-direction: column; gap: 12px; width: 124px; flex-shrink: 0; }
.mbx-group__side-item { display: flex; flex-direction: column; cursor: pointer; }
.mbx-group__side-img { position: relative; width: 124px; height: 84px; border-radius: 16px; overflow: hidden; background: var(--background-secondary, #f1f1f1); }
.mbx-group__store { font-family: var(--font-body); font-size: 11px; font-weight: 500; line-height: 16px; color: var(--foreground-secondary, #606060); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbx-group__side-name { font-family: var(--font-body); font-size: 12px; font-weight: 500; line-height: 18px; color: var(--foreground-primary, #191919); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbx-esr .section-header__chevron { width: 32px; height: 32px; border-radius: 9999px; background: var(--background-secondary, #f1f1f1); justify-content: center; }
.mbx-esr__scroll { display: flex; gap: 12px; overflow-x: auto; padding: 0px 16px; scrollbar-width: none; }
.mbx-esr__scroll::-webkit-scrollbar { display: none; }
.mbx-esr-card { flex-shrink: 0; width: 320px; cursor: pointer; }
.mbx-esr-card__img { width: 100%; height: 180px; border-radius: 12px; overflow: hidden; background: var(--background-secondary, #f1f1f1); }
.mbx-esr-card__img img { width: 100%; height: 100%; object-fit: cover; display: block; }
.mbx-esr-card__name-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 8px; }
.mbx-esr-card__name { font-family: var(--font-body); font-size: 16px; font-weight: 700; line-height: 22px; letter-spacing: -0.01em; color: var(--foreground-primary, #191919); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0px; }
.mbx-esr-card__fav { display: flex; align-items: center; flex-shrink: 0; }
.mbx-esr-card__meta { display: flex; align-items: center; gap: 4px; margin-top: 2px; font-family: var(--font-body); font-size: 12px; line-height: 18px; color: var(--foreground-secondary, #606060); }
.mbx-esr-card__meta-rest { font-weight: 500; }
.mbx-esr-card__fee { font-family: var(--font-body); font-size: 12px; font-weight: 500; line-height: 18px; color: var(--foreground-secondary, #606060); margin-top: 1px; }
.mbx-esr-card__badges { display: flex; align-items: center; gap: 6px; margin-top: 6px; flex-wrap: wrap; }
.mbx-nv-grocery__scroll { overflow-x: auto; padding: 0px 16px; scrollbar-width: none; }
.mbx-nv-grocery__scroll::-webkit-scrollbar { display: none; }
.mbx-nv-grocery .psc--list .psc__img { object-fit: contain; background: var(--surface-primary, #fff); border: 1px solid var(--stroke-tertiary, #e4e4e4); }
.mbx-rail--stores .psc--medium .psc__img { height: 140px; object-fit: cover; }
.mbx-spot__card { position: relative; display: block; width: calc(100% - 32px); height: 210px; margin: 0px 16px 12px; padding: 0px; border: 0px; border-radius: var(--usage-border-radius-x-large, 24px); overflow: hidden; background: linear-gradient(135deg, rgb(126, 26, 16), rgb(159, 36, 22) 46%, rgb(184, 58, 25)); color: rgb(255, 255, 255); text-align: center; cursor: pointer; user-select: none; -webkit-tap-highlight-color: transparent; font-family: var(--usage-font-family-default, "DD Norms", sans-serif); transition: transform 0.12s; }
.mbx-spot__card:active { transform: scale(0.985); }
.mbx-spot__lockup { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; height: 100%; box-sizing: border-box; padding: 30px 32px; text-align: center; position: relative; z-index: 3; }
.mbx-spot__bg { position: absolute; inset: 0px; z-index: 1; overflow: hidden; border-radius: inherit; pointer-events: none; }
.mbx-spot__scrim { position: absolute; inset: 0px; z-index: 2; background: rgba(0, 0, 0, 0.34); border-radius: inherit; pointer-events: none; }
.mbx-spot__wip { margin: 2px 0px; font-size: 10px; font-weight: var(--usage-font-weight-strong, 700); line-height: 12px; letter-spacing: 0.14em; text-transform: uppercase; color: rgba(255, 255, 255, 0.58); }
.mbx-spot__blob { position: absolute; border-radius: 9999px; }
.mbx-spot__blob--orange { width: 260px; height: 260px; top: -130px; right: -70px; background: radial-gradient(circle, rgba(255, 138, 43, 0.55), rgba(255, 138, 43, 0) 70%); }
.mbx-spot__blob--yellow { width: 210px; height: 210px; bottom: -110px; left: -60px; background: radial-gradient(circle, rgba(255, 198, 77, 0.38), rgba(255, 198, 77, 0) 70%); }
.mbx-spot__blob--ember { width: 170px; height: 170px; top: -30px; left: 50%; margin-left: -85px; background: radial-gradient(circle, rgba(255, 106, 26, 0.32), rgba(255, 106, 26, 0) 68%); }
.mbx-spot__blob--deep { width: 220px; height: 220px; bottom: -120px; right: -60px; background: radial-gradient(circle, rgba(94, 18, 10, 0.45), rgba(94, 18, 10, 0) 70%); }
.mbx-spot__seal-img { display: block; width: 74px; height: 74px; }
.mbx-spot__wordmark { font-family: var(--usage-font-family-brand, "DD Norms", sans-serif); font-weight: var(--usage-font-weight-xstrong, 800); font-size: 22px; line-height: 26px; letter-spacing: -0.2px; color: rgb(255, 255, 255); }
.mbx-spot__pill { display: inline-flex; align-items: center; gap: 2px; padding: 7px 12px; border-radius: 9999px; background: rgb(255, 255, 255); font-size: 13px; font-weight: var(--usage-font-weight-strong, 700); line-height: 16px; color: rgb(159, 36, 22); }
.mbx-spot__pill svg { display: block; margin-right: -2px; }
.mbx-spot__head { padding: 16px 16px 0px; }
.mbx-spot__title { margin: 0px; font-family: var(--usage-font-family-brand, "DD Norms", sans-serif); font-weight: var(--usage-font-weight-xstrong, 800); font-size: 20px; line-height: 24px; letter-spacing: -0.2px; color: var(--foreground-primary, #191919); }
.mbx-spot__sub { margin: 0px; font-size: 16px; font-weight: var(--usage-font-weight-default, 500); line-height: 22px; color: var(--foreground-secondary, #606060); }
.mbx-spot .mbx-spot__card { margin-bottom: 0px; }
.mbx-spot__rail { margin-top: 12px; }
.mbx-dainty { margin: 8px 16px 4px; width: calc(100% - 32px); min-height: 44px; padding: 0px 12px; display: flex; align-items: center; gap: 10px; border-radius: 8px; background: rgb(247, 247, 247); border: 0px; text-align: left; cursor: pointer; }
.mbx-dainty:active { background: rgb(241, 241, 241); }
.mbx-dainty__glyph { display: flex; align-items: center; justify-content: center; flex-shrink: 0; width: 20px; height: 20px; }
.mbx-dainty__copy { flex: 1 1 0%; min-width: 0px; padding: 10px 0px; font-size: 14px; font-weight: 700; line-height: 20px; color: rgb(25, 25, 25); }
.mbx-dainty__learn { flex-shrink: 0; display: flex; align-items: center; gap: 2px; font-size: 14px; font-weight: 700; line-height: 20px; color: rgb(25, 25, 25); }
.mbx-subline { padding: 0px 16px; margin: 2px 0px 4px; font-size: 14px; font-weight: 500; line-height: 20px; color: rgb(96, 96, 96); }
.mbx-subline__link { font-weight: 700; color: rgb(25, 25, 25); background: none; border: 0px; padding: 0px 4px 0px 0px; margin: -6px 0px; font-size: inherit; line-height: inherit; display: inline; cursor: pointer; }
.mbx-subline__info { display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px; margin: -10px 0px -10px -6px; padding: 0px; border: 0px; background: none; color: var(--foreground-secondary, #606060); cursor: pointer; }
